import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Fused ConvTranspose2d + BatchNorm + Tanh kernel
conv_bn_tanh_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>
#include <ATen/cuda/CUDAContext.h>
#include <ATen/ATen.h>
#include <ATen/cuda/detail/IndexUtils.cuh>

#define CUDA_CHECK(err) do { if (err != cudaSuccess) { \
    printf("%s in %s at line %d\\n", cudaGetErrorString(err), __FILE__, __LINE__); \
    exit(EXIT_FAILURE);}} while (0)

__global__ void fused_conv_bn_tanh_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    float* __restrict__ output,
    int C_in, int C_out, int K, int H_in, int W_in, int H_out, int W_out,
    int stride, int padding, float eps) {

    const int n = blockIdx.z;
    const int c = blockIdx.y;
    const int h = blockIdx.x * blockDim.y + threadIdx.y;
    const int w = threadIdx.x;

    if (h >= H_out || w >= W_out) return;

    float sum = 0.0f;

    #pragma unroll
    for (int kh = 0; kh < K; ++kh) {
        #pragma unroll
        for (int kw = 0; kw < K; ++kw) {
            const int h_in = h * stride - padding + kh;
            const int w_in = w * stride - padding + kw;

            if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
                #pragma unroll
                for (int c_in = 0; c_in < C_in; ++c_in) {
                    float val = input[n * C_in * H_in * W_in + c_in * H_in * W_in + h_in * W_in + w_in];
                    float wgt = weight[c * C_in * K * K + c_in * K * K + kh * K + kw];
                    sum += val * wgt;
                }
            }
        }
    }

    sum += bias[c];
    float mean = running_mean[c];
    float var = running_var[c];
    float inv_std = rsqrtf(var + eps);
    float norm = (sum - mean) * inv_std;
    output[n * C_out * H_out * W_out + c * H_out * W_out + h * W_out + w] = tanhf(norm);
}

torch::Tensor fused_conv_bn_tanh_cuda(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    torch::Tensor running_mean, torch::Tensor running_var,
    int stride, int padding, float eps) {

    auto N = input.size(0);
    auto C_in = input.size(1);
    auto H_in = input.size(2);
    auto W_in = input.size(3);
    auto C_out = weight.size(0);
    auto K = weight.size(2);

    int H_out = (H_in - 1) * stride + K - 2 * padding;
    int W_out = (W_in - 1) * stride + K - 2 * padding;

    auto output = torch::empty({N, C_out, H_out, W_out}, 
        torch::TensorOptions().dtype(input.dtype()).device(input.device()));

    dim3 block(32, 4);
    dim3 grid((H_out + block.y - 1) / block.y, C_out, N);

    fused_conv_bn_tanh_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        output.data_ptr<float>(),
        C_in, C_out, K, H_in, W_in, H_out, W_out,
        stride, padding, eps);

    CUDA_CHECK(cudaGetLastError());
    return output;
}
"""

# Fused MaxPool + GroupNorm kernel
pool_gn_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cub/cub.cuh>

__global__ void fused_pool_gn_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    int N, int C, int H, int W,
    int pool_size, int groups, float eps) {

    const int n = blockIdx.z;
    const int g = blockIdx.y;
    const int c_start = g * (C / groups);
    const int c_end = (g + 1) * (C / groups);
    const int h = blockIdx.x * blockDim.x + threadIdx.x;
    const int w = threadIdx.y;

    if (h >= H || w >= W) return;

    __shared__ float shmem[32][32];
    float max_val = -FLT_MAX;

    // Max pooling
    for (int ph = 0; ph < pool_size; ++ph) {
        for (int pw = 0; pw < pool_size; ++pw) {
            int h_in = h * pool_size + ph;
            int w_in = w * pool_size + pw;
            if (h_in < H*pool_size && w_in < W*pool_size) {
                for (int c = c_start; c < c_end; ++c) {
                    float val = input[n * C * H*2 * W*2 + c * H*2 * W*2 + h_in * W*2 + w_in];
                    max_val = fmaxf(max_val, val);
                }
            }
        }
    }
    shmem[threadIdx.x][threadIdx.y] = max_val;
    __syncthreads();

    // GroupNorm
    float sum = 0.0f, sq_sum = 0.0f;
    for (int i = 0; i < blockDim.x; ++i) {
        for (int j = 0; j < blockDim.y; ++j) {
            float val = shmem[i][j];
            sum += val;
            sq_sum += val * val;
        }
    }

    float mean = sum / (H * W * (C / groups));
    float var = (sq_sum / (H * W * (C / groups))) - mean * mean;
    float inv_std = rsqrtf(var + eps);

    for (int c = c_start; c < c_end; ++c) {
        float norm = (max_val - mean) * inv_std;
        output[n * C * H * W + c * H * W + h * W + w] = norm * weight[c] + bias[c];
    }
}

torch::Tensor fused_pool_gn_cuda(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    int pool_size, int groups, float eps) {

    auto N = input.size(0);
    auto C = input.size(1);
    auto H_in = input.size(2);
    auto W_in = input.size(3);

    int H = H_in / pool_size;
    int W = W_in / pool_size;

    auto output = torch::empty({N, C, H, W}, 
        torch::TensorOptions().dtype(input.dtype()).device(input.device()));

    dim3 block(16, 16);
    dim3 grid((H + block.x - 1) / block.x, groups, N);

    fused_pool_gn_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        N, C, H, W, pool_size, groups, eps);

    cudaDeviceSynchronize();
    return output;
}
"""

# Load custom CUDA modules
conv_bn_tanh = load_inline(
    name='conv_bn_tanh',
    cpp_sources="torch::Tensor fused_conv_bn_tanh_cuda(torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor, torch::Tensor, int, int, float);",
    cuda_sources=conv_bn_tanh_source,
    functions=['fused_conv_bn_tanh_cuda'],
    verbose=True
)

pool_gn = load_inline(
    name='pool_gn',
    cpp_sources="torch::Tensor fused_pool_gn_cuda(torch::Tensor, torch::Tensor, torch::Tensor, int, int, float);",
    cuda_sources=pool_gn_source,
    functions=['fused_pool_gn_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, groups, num_groups):
        super().__init__()
        self.conv_weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size, kernel_size))
        self.conv_bias = nn.Parameter(torch.empty(out_channels))
        self.register_buffer('running_mean', torch.zeros(out_channels))
        self.register_buffer('running_var', torch.ones(out_channels))
        self.gn_weight = nn.Parameter(torch.ones(out_channels))
        self.gn_bias = nn.Parameter(torch.zeros(out_channels))
        self.stride = stride
        self.padding = padding
        self.groups = num_groups
        self.eps = 1e-5
        self.pool_size = 2

        nn.init.kaiming_normal_(self.conv_weight)
        nn.init.zeros_(self.conv_bias)

    def forward(self, x):
        x = conv_bn_tanh.fused_conv_bn_tanh_cuda(
            x, self.conv_weight, self.conv_bias,
            self.running_mean, self.running_var,
            self.stride, self.padding, self.eps)

        x = pool_gn.fused_pool_gn_cuda(
            x, self.gn_weight, self.gn_bias,
            self.pool_size, self.groups, self.eps)

        return x
